        for row in mat:
            if row:
                res.append(row.pop())
        # bottom row (if any)
        if mat:
            bottom = mat.pop()
            if bottom:
                res.extend(bottom[::-1])
        # left column
        for row in reversed(mat):
            if row:
                res.append(row.pop(0))
        # remove empty rows
        mat = [row for row in mat if row]
    return res

