import random, itertools

def solve(nums):
    a = list(nums)
    n = len(a)
    if n <= 1:
        return a
    i = n - 2
    while i >= 0 and a[i] >= a[i+1]:
        i -= 1
    if i < 0:
        return sorted(a)
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    a[i+1:] = reversed(a[i+1:])
    return a

def ref(nums):
    # generate all permutations, sort them lexicographically, find next
    perms = sorted(set(itertools.permutations(nums)))
    try:
        idx = perms.index(tuple(nums))
        if idx+1 < len(perms):
            return list(perms[idx+1])
    except ValueError:
        pass
    return list(sorted(nums))

for _ in range(1000):
    length = random.randint(0,5)
    arr = [random.randint(0,3) for _ in range(length)]
    if solve(arr) != ref(arr):
        print('mismatch',arr,solve(arr),ref(arr))
        break
else:
    print('all ok')

